import{_ as l,o as t,c as r,a2 as o}from"./chunks/framework.mRCPFc5l.js";const q=JSON.parse('{"title":"叙事与玩家","description":"","frontmatter":{},"headers":[],"relativePath":"底层/规则/叙事与玩家.md","filePath":"底层/规则/叙事与玩家.md","lastUpdated":null}'),e={name:"底层/规则/叙事与玩家.md"};function i(n,a,s,h,u,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="叙事与玩家" tabindex="-1">叙事与玩家 <a class="header-anchor" href="#叙事与玩家" aria-label="Permalink to &quot;叙事与玩家&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>叙事与玩家是神造物世界观的底层元规则。本世界观存在深层的<strong>叙事逻辑</strong>，影响故事发展与角色命运；而<strong>玩家</strong>作为特殊的叙事存在，拥有不同于故事内角色的地位与能力。</p><h2 id="叙事层级结构" tabindex="-1">叙事层级结构 <a class="header-anchor" href="#叙事层级结构" aria-label="Permalink to &quot;叙事层级结构&quot;">​</a></h2><ul><li><strong>层级结构</strong>：<strong>叙事逻辑 → 作者/玩家/读者（上层叙事存在） → 神明 → 世界角色</strong></li><li><strong>叙事逻辑凌驾于作者之上</strong>——因为作者也要遵守叙事逻辑</li></ul><h2 id="叙事逻辑" tabindex="-1">叙事逻辑 <a class="header-anchor" href="#叙事逻辑" aria-label="Permalink to &quot;叙事逻辑&quot;">​</a></h2><h3 id="基本特征" tabindex="-1">基本特征 <a class="header-anchor" href="#基本特征" aria-label="Permalink to &quot;基本特征&quot;">​</a></h3><ul><li>世界运行并非纯粹理性，存在某种&quot;故事性&quot;的规律</li><li>初代变化神最早发现&quot;这个世界不是那么讲逻辑&quot;，并将这一认知传给奥克尔；神机从前传中学习到这一点，并成为最深入的实践者</li></ul><h3 id="叙事逻辑影响角色命运" tabindex="-1">叙事逻辑影响角色命运 <a class="header-anchor" href="#叙事逻辑影响角色命运" aria-label="Permalink to &quot;叙事逻辑影响角色命运&quot;">​</a></h3><p>叙事逻辑会影响角色命运。例如：维斯塔许下无法完成的宏愿，本应消亡，但故事逻辑需要他活着——神机以&quot;立新规&quot;的方式介入（而非直接捞回），维斯塔因新规卡入悖论而存活。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../中层/世界/地脉与魔法" class="layer-link" data-layer="中层">地脉与魔法</a></p></blockquote><h3 id="上层叙事存在" tabindex="-1">上层叙事存在 <a class="header-anchor" href="#上层叙事存在" aria-label="Permalink to &quot;上层叙事存在&quot;">​</a></h3><ul><li>玩家、作者、读者均属<strong>上层叙事存在</strong></li><li>世界内任何角色（包括神明）都<strong>无法直接证明其存在与否</strong>（直接不可能，而非间接不可能）</li><li>神机则通过事实与蛛丝马迹<strong>推算</strong>出了叙事逻辑与作者的存在</li></ul><h3 id="神机与叙事博弈" tabindex="-1">神机与叙事博弈 <a class="header-anchor" href="#神机与叙事博弈" aria-label="Permalink to &quot;神机与叙事博弈&quot;">​</a></h3><p>神机基于对叙事逻辑的认知，与叙事本身展开博弈：刻意不进入叙事（正传中几乎不露面），控制故事走向，为毁灭神的出现打基础，保证其可控。</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../中层/世界/神机谋划" class="layer-link" data-layer="中层">神机谋划</a></p></blockquote><h2 id="玩家" tabindex="-1">玩家 <a class="header-anchor" href="#玩家" aria-label="Permalink to &quot;玩家&quot;">​</a></h2><h3 id="两种玩家的区分" tabindex="-1">两种玩家的区分 <a class="header-anchor" href="#两种玩家的区分" aria-label="Permalink to &quot;两种玩家的区分&quot;">​</a></h3><ul><li>前传中的&quot;玩家&quot;是<strong>故事内的角色</strong>（虚拟人类远程附身克隆人）</li><li>正传中可存档读档的&quot;玩家&quot;才是<strong>真实、电脑前的玩家</strong></li><li>两者完全不同</li></ul><h3 id="玩家的能力" tabindex="-1">玩家的能力 <a class="header-anchor" href="#玩家的能力" aria-label="Permalink to &quot;玩家的能力&quot;">​</a></h3><ul><li>可<strong>存档、读档</strong></li><li>可回到<strong>不同时间线上的某一时刻</strong></li><li>可<strong>创造平行世界线</strong></li><li>这是故事内任何存在（含神明）都不具备的特权</li></ul><h3 id="玩家能力与观测" tabindex="-1">玩家能力与观测 <a class="header-anchor" href="#玩家能力与观测" aria-label="Permalink to &quot;玩家能力与观测&quot;">​</a></h3><ul><li>没有任何故事内的角色能够<strong>直接</strong>察觉到玩家的&quot;读档&quot;行为</li><li>即使是最强大的神明，也无法<strong>直接跨越时间线进行观测</strong>——但<strong>间接察觉是完全可行的</strong>：神明与敏锐角色可以透过蛛丝马迹感知到世界运行逻辑的异常</li></ul><h3 id="叙事逻辑特征" tabindex="-1">叙事逻辑特征 <a class="header-anchor" href="#叙事逻辑特征" aria-label="Permalink to &quot;叙事逻辑特征&quot;">​</a></h3><ul><li>玩家的叙事逻辑与故事本身的逻辑不同：玩家角色会以<strong>异于常理的速度</strong>强大起来，在&quot;游戏&quot;所包括的时间段内，他们似乎<strong>总能走向成功</strong></li><li>其他角色的人生有起承转合，结局可能是成功也可能是悲剧；但玩家的叙事即使有波动，最终也是<strong>快速强大，走向成功</strong></li></ul><h2 id="时间线不可干预性" tabindex="-1">时间线不可干预性 <a class="header-anchor" href="#时间线不可干预性" aria-label="Permalink to &quot;时间线不可干预性&quot;">​</a></h2><ul><li><strong>时间是一个很现实、很底层的设定</strong>——未来、过去没人能动，包括神机也无法干预时间线</li><li>时间线不是不能动的，但只有<strong>玩家</strong>作为特殊的叙事存在可以对时间线进行操作（存档、读档、创造平行世界线）</li><li>即使是毁灭神，也只能删除当下的存在（如狼族的基因锁），无法删除所有时间线上的存在</li><li>甚至未来、过去、时间线是否真实存在，都是个问号，构成了世界观的核心伏笔之一</li></ul><h2 id="黑化支线与平行时间线" tabindex="-1">黑化支线与平行时间线 <a class="header-anchor" href="#黑化支线与平行时间线" aria-label="Permalink to &quot;黑化支线与平行时间线&quot;">​</a></h2><p>维斯塔黑化的平行时间线等具体内容属于支线节点设定，本文档不再展开：</p><blockquote><p><strong>详细内容参见</strong>：<a href="./../../叙事与伏笔/维斯塔黑化">维斯塔黑化</a></p></blockquote><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><p><a href="./../../叙事与伏笔/伏笔洋葱层分类">伏笔洋葱层分类</a></p></li><li><p><a href="./神权体系">神权体系</a></p></li><li><p><a href="./基底层与现实世界">基底层与现实世界</a></p></li><li><p><a href="./../../中层/世界/神机谋划" class="layer-link" data-layer="中层">神机谋划</a></p></li><li><p><a href="./../../叙事与伏笔/维斯塔黑化">维斯塔黑化</a></p></li></ul><hr>',34)])])}const g=l(e,[["render",i]]);export{q as __pageData,g as default};
